"""Alternative-hypothesis ranking with direct-cue weighting.

The model often gives Neutral many generic visual support ids while assigning a
specific facial or vocal cue to a competing label. This ranker keeps confidence
important, but rewards specific affective evidence and discounts unsupported or
incidental volume.
"""

from __future__ import annotations

from typing import Any

DIRECT_TERMS = (
    'smil', 'Smil', 'laugh', 'Laugh', 'grin', 'Grin', 'frown', 'Frown',
    'furrow', 'Furrow', 'wide eyes', 'Wide eyes', 'eyes wide', 'Eyes wide',
    'open mouth', 'Open mouth', 'raised eyebrow', 'Raised eyebrow',
    'looks down', 'Looks down', 'covers face', 'Covers face', 'gestur',
    'Gestur', 'leans', 'Leans', 'hands outward', 'Hands outward', 'tears',
    'Tears', 'cry', 'Cry', 'tense', 'Tense', 'clench', 'Clench', 'shake',
    'Shake', 'scream', 'Scream', 'yell', 'Yell', 'abrasive', 'Abrasive',
    'quiet voice', 'Quiet voice', 'long pauses', 'Long pauses',
    'high pitch', 'High pitch', 'low pitch', 'Low pitch'
)


def rank(record: dict[str, Any], hypotheses: dict[str, Any]) -> list[dict[str, Any]]:
    """Order hypotheses by confidence plus quality of their cited evidence."""
    rows = []
    index = 0
    for hypothesis in hypothesis_list(hypotheses):
        confidence = confidence_of(hypothesis)
        direct = direct_support_score(record, hypothesis)
        support = support_count(record, hypothesis)
        contradiction = contradiction_count(record, hypothesis)
        score = confidence * 10.0 + direct - contradiction * 0.15
        rows = rows + [(-score, -confidence, -direct, -support, index, hypothesis)]
        index = index + 1
    ordered = sorted(rows)
    return [row[5] for row in ordered]


def confidence_of(hypothesis: dict[str, Any]) -> float:
    if 'confidence' in hypothesis:
        return float(hypothesis['confidence'])
    return 0.0


def direct_support_score(record: dict[str, Any], hypothesis: dict[str, Any]) -> float:
    known = known_items(record)
    score = 0.0
    for item_id in id_list(hypothesis, 'support'):
        key = str(item_id)
        if key in known:
            item = known[key]
            cue = str(item['cue'])
            value = cue_value(cue)
            modality = str(item['modality'])
            if modality == 'audio':
                value = value + 0.25
            if modality == 'visual':
                value = value + 0.15
            score = score + value
    return score


def cue_value(cue: str) -> float:
    value = 0.0
    for term in DIRECT_TERMS:
        if term in cue:
            value = value + 0.55
    if value > 1.65:
        return 1.65
    return value


def contradiction_count(record: dict[str, Any], hypothesis: dict[str, Any]) -> int:
    known = known_ids(record)
    count = 0
    for item_id in id_list(hypothesis, 'contradiction'):
        if str(item_id) in known:
            count = count + 1
    return count


def support_count(record: dict[str, Any], hypothesis: dict[str, Any]) -> int:
    known = known_ids(record)
    count = 0
    for item_id in id_list(hypothesis, 'support'):
        if str(item_id) in known:
            count = count + 1
    return count


def known_items(record: dict[str, Any]) -> dict[str, Any]:
    result = {}
    for item in item_list(record):
        result[str(item['id'])] = item
    return result


def known_ids(record: dict[str, Any]) -> set[str]:
    result = set()
    for item in item_list(record):
        result.add(str(item['id']))
    return result


def item_list(record: dict[str, Any]) -> list[Any]:
    if 'items' in record:
        return list(record['items'])
    return []


def hypothesis_list(hypotheses: dict[str, Any]) -> list[Any]:
    if 'hypotheses' in hypotheses:
        return list(hypotheses['hypotheses'])
    return []


def id_list(hypothesis: dict[str, Any], key: str) -> list[Any]:
    if key in hypothesis:
        return list(hypothesis[key])
    return []
